// One typed table for adopted S0 snapshots; no runtime ReadStamp is serialized.
#pragma once
#include "propagation_disposition_read.hpp"
#include "resident/domains/actor_foundation/character_origin_codec_detail.hpp"
namespace hanmo::resident::propagation_disposition_codec {
template<class C>Status contribution(C& c,SocialEvaluationContributionRef& v){c.field("evaluation_id",v.evaluation_id);c.field("revision",v.revision);return v.evaluation_id.empty()||v.revision<1?c.reject("InvalidSocialEvaluationContributionRef"):c.status();}
template<class C>Status relation(C& c,RelationProjection& v){
 c.field("from_actor_id",v.from_actor_id);c.field("to_actor_id",v.to_actor_id);
 c.object("basis",[&](auto& x){Integer tag=static_cast<Integer>(v.basis.index());x.field("tag",tag);if(tag<0||tag>1)return x.reject("InvalidSocialRelationBasis");if(x.reading())v.basis=tag==0?SocialRelationBasis{RecordedRelationBasis{}}:SocialRelationBasis{NoRecordedRelationBasis{}};return std::visit([&](auto& b){x.field("from_actor_id",b.from_actor_id);x.field("to_actor_id",b.to_actor_id);if constexpr(std::is_same_v<std::decay_t<decltype(b)>,RecordedRelationBasis>)x.optional("record_id",b.record_id,[](auto& y,auto& id){return y.field("value",id);});else x.object("original_zero_rule_ref",[&](auto& y){return character_origin_codec::rule(y,b.original_zero_rule_ref);});return b.from_actor_id!=v.from_actor_id||b.to_actor_id!=v.to_actor_id?x.reject("SocialRelationBasisActorMismatch"):x.status();},v.basis);});
 c.field("effective_trust",v.effective_trust);c.field("effective_affinity",v.effective_affinity);c.sequence("current_contribution_refs",v.current_contribution_refs,[](auto& x,auto& ref){return contribution(x,ref);});
 if(v.from_actor_id.empty()||v.to_actor_id.empty()||v.effective_trust<0||v.effective_trust>100||v.effective_affinity<0||v.effective_affinity>100)return c.reject("InvalidRelationProjection");
 for(std::size_t i=0;i<v.current_contribution_refs.size();++i)for(std::size_t j=0;j<i;++j)if(v.current_contribution_refs[i].evaluation_id==v.current_contribution_refs[j].evaluation_id)return c.reject("DuplicateSocialEvaluationContribution");return c.status();
}
template<class C>Status known_policy(C& c,KnownSocialPolicyBasis& v){
 c.object("policy_source",[&](auto& x){x.object("catalog_identity",[&](auto& y){return character_origin_codec::catalog(y,v.policy_source.catalog_identity);});Integer lookup=static_cast<Integer>(v.policy_source.lookup);x.field("lookup",lookup);if(lookup<0||lookup>1)return x.reject("InvalidSocialPolicyLookup");if(x.reading())v.policy_source.lookup=static_cast<SocialPolicySource::Lookup>(lookup);return x.field("policy_actor_key",v.policy_source.policy_actor_key);});
 Integer kind=static_cast<Integer>(v.kind);c.field("kind",kind);if(kind<0||kind>1)return c.reject("InvalidSocialPolicyKind");if(c.reading())v.kind=static_cast<KnownSocialPolicyBasis::Kind>(kind);c.field("share_news",v.share_news);c.field("interval_ticks",v.interval_ticks);return v.policy_source.policy_actor_key.empty()||v.interval_ticks<1||v.interval_ticks>120?c.reject("InvalidKnownSocialPolicy"):c.status();
}
template<class C>Status policy(C& c,SocialDispositionPolicyBasis& v){Integer tag=static_cast<Integer>(v.index());c.field("tag",tag);if(tag<0||tag>1)return c.reject("InvalidSocialDispositionPolicy");if(c.reading())v=tag==0?SocialDispositionPolicyBasis{UnknownSocialPolicyBasis{}}:SocialDispositionPolicyBasis{KnownSocialPolicyBasis{}};if(tag==1)return known_policy(c,std::get<KnownSocialPolicyBasis>(v));auto& unknown=std::get<UnknownSocialPolicyBasis>(v);Integer reason=static_cast<Integer>(unknown.reason);c.field("reason",reason);return reason!=0?c.reject("InvalidUnknownSocialPolicyReason"):c.status();}
template<class C>Status disposition(C& c,PropagationDispositionV1& v){c.field("sender_actor_id",v.sender_actor_id);c.field("candidate_receiver_actor_id",v.candidate_receiver_actor_id);c.object("policy_basis",[&](auto& x){return policy(x,v.policy_basis);});c.object("relation_projection",[&](auto& x){return relation(x,v.relation_projection);});c.object("observed_at",[&](auto& x){return family_life4_codec::moment(x,v.observed_at);});return v.sender_actor_id!=v.relation_projection.from_actor_id||v.candidate_receiver_actor_id!=v.relation_projection.to_actor_id?c.reject("PropagationRelationActorMismatch"):c.status();}
}
